# In[3]:


def proportionality(A,B):
    j = next((i for i,a in enumerate(sp.flatten(A.tolist())) if a),None)
    a = sp.flatten(A.tolist())[j] if j!=None else 0
    b = sp.flatten(B.tolist())[j] if j!=None else 0
    return sp.simplify(b/a) if (a != 0 and sp.simplify(b*A-a*B)==sp.Array(sp.zeros(len(A)),A.shape)) else "A = 0" if a==0 else "not proportional"


# In[4]:


#The next function computes gamma(n/2) for an integer n:
def half_gamma(n):
    return sp.sqrt(pi)*sp.factorial2(n-2)/2**sp.floor(n/2) if n%2==1 else sp.factorial(n/2-1)

#This uses the classic formula for integrating a monomial over a sphere (see Folland's article in AMM May 2001)
def int_mon_over_sphere(t):
    t=sp.sympify(t)
    t_offset = list(map(lambda x : x + 1,t))
    return 2*reduce(mul,list(map(lambda x : half_gamma(x) if x%2==1 else 0, t_offset)))/half_gamma(reduce(add,t_offset))

#This takes a polynomial (as an expression, internally converted into a polynomial from sympy.polys) and integrates it over the sphere of radius 1.
#Note that the number of variables is fixed by the line above.
def int_poly_over_sphere(p):
    p_internal=poly(p,x)
    return reduce(add,[term[1]*int_mon_over_sphere(term[0]) for term in list(p_internal.terms())])

#divides the result of int_poly_over_sphere(p) by the surface volume of the sphere.
def avg_poly_over_sphere(p):
    return int_poly_over_sphere(p)/int_poly_over_sphere(poly(1,x))

#This takes the inner product of two real-variable polynomials over the sphere (their coefficients may be complex).
def poly_inner_product(p,q):
    return avg_poly_over_sphere(sp.conjugate(p)*q)


# In[5]:

def commutator(A,B):
    return A*B - B*A
def form_commutator(Psi1,Psi2):
    Psi1_int = [sp.Matrix(Psi1[i]) for i in range(Psi1.shape[0])]
    Psi2_int = [sp.Matrix(Psi2[i]) for i in range(Psi2.shape[0])]
    return sp.Array([(Psi1_int[i]*Psi2_int[i] - Psi2_int[i]*Psi1_int[i]).tolist()
                     for i in range(Psi1.shape[0])])
def tensorform(v,A):
    return sp.tensorproduct(v,A)[0] if v.shape[0]==1 else sp.tensorproduct(v.transpose(),A)[0]
def form_pointwise_inner_product(Psi1,Psi2):
    psi1 = sp.flatten(Psi1)
    psi2 = sp.flatten(Psi2)
    return sum([sp.conjugate(psi1[j])*psi2[j] for j in range(len(psi1))])
def form_inner_product(Psi1,Psi2):
    return avg_poly_over_sphere(form_pointwise_inner_product(Psi1,Psi2))
def form_norm(Psi):
    entries=Psi.applyfunc(lambda x: sp.conjugate(x)*x).tolist()
    return sum([x for xss in entries for xs in xss for x in xs])


