def act_on_polynomial(A,p):
    return sp.factor(sum([(A*sp.Matrix(x))[i]*sp.diff(p,x[i]) for i in range(len(x))]))
    
def act_on_form(A,Psi):
    v_A = A*sp.Matrix(x)
    Psi_int = [sp.Matrix(Psi[i]) for i in range(Psi.shape[0])]
    return sp.Array([(A*Psi_int[i] - Psi_int[i]*A
            - sum([v_A[j]*sp.diff(Psi_int[i],x[j]) for j in range(len(x))],sp.zeros(5))
            - sum([A[j,i]*Psi_int[j] for j in range(len(x))],sp.zeros(5))
            ).tolist()
            for i in range(Psi.shape[0])])


# In[8]:


negative_weights = [sp.Matrix((-1,1)),sp.Matrix((-1,0)),sp.Matrix((-1,-1)),sp.Matrix((0,-1))]

def collect_paths(weight1,weight2):
    weight1 = sp.Matrix(weight1)
    weight2 = sp.Matrix(weight2)
    return collect_restricted_paths(weight1,weight2,len(negative_weights))

def collect_restricted_paths(weight1,weight2,k):
    list_of_paths = []
    if weight1 == weight2:
        return [[]]
    if weight1[0]**2+weight1[1]**2 < weight2[0]**2+weight2[1]**2:
        return 0
    for j in range(k):
        if collect_restricted_paths(weight1,weight2-negative_weights[j],j+1) != 0:
            list_of_paths = list_of_paths+[path+[negative_weights[j]] for path in collect_restricted_paths(weight1,weight2-negative_weights[j],j+1)]
    if list_of_paths == []:
        return 0
    return list_of_paths

def print_path(path):
    list = [v.tolist() for v in path]
    display(sp.Array(list))

def print_paths(list_of_paths):
    for path in list_of_paths: print_path(path) 

def get_weight_vectors(highest_weight_vector,highest_weight,weight,action):
    weight1 = highest_weight
    weight2 = weight
    paths = collect_paths(weight1,weight2)
    vector_list = []
    if paths != 0:
        for path in paths:
            vector = highest_weight_vector
            for l in path:
                vector = action(adRep[tuple(sp.flatten(l.tolist()))],vector)
            vector_list = vector_list+[vector]
    return vector_list

def get_smaller_weights(weight):
    size = sum(map(lambda x:x*x,weight))
    return [el for el in itertools.product(*[range(-weight[j],weight[j]+1) for j in range(len(weight))])
            if sum(map(lambda x:x*x,el)) <= size]

def get_smaller_positive_weights(weight):
    size = sum(map(lambda x:x*x,weight))
    return list(reversed([el for el in itertools.product(*[range(-max(weight),max(weight)+1) for j in range(len(weight))])
            if sum(map(lambda x:x*x,el)) <= size and all([j[0]>=j[1] for j in zip(el,el[1:])]) and el[len(weight)-1]>=0]))
    
def act_with_function(action,v):
    return action(T1,v)

def gram_schmidt_orthogonalize(vector_list,inner_product):
    new_list = []
    for v in vector_list:
        v_new = v
        for w in new_list:
            v_new = v_new - inner_product(w,v_new)/inner_product(w,w)*w
        if inner_product(v_new,v_new) != 0:
            new_list = new_list+[sp.simplify(v_new)]
    return new_list

def orthogonal_projection(vector,vector_list,inner_product):
    new_list = gram_schmidt_orthogonalize(vector_list,inner_product)
    v=vector
    for w in new_list:
        v = v - inner_product(w,v)/inner_product(w,w)*w
    return v
    
def row_reduce_array_list(array_list):
    return [sp.Array(reduced_array,array_list[0].shape)
            for reduced_array in sp.Matrix([sp.flatten(array) for array in array_list]).rref()[0].tolist() if not all(v == 0 for v in reduced_array)]
    
def clear_linear_dependence_from_array_list(array_list):
    return [sp.Array(reduced_array, array_list[0].shape)
            for reduced_array in sp.Matrix([sp.flatten(array) for array in array_list]).transpose().columnspace()]

def clear_denominators_from_array_list(array_list):
    return [sp.simplify(array/sp.gcd([sp.fraction(n)[0] for n in sp.flatten(array) if n != 0])) for array in array_list if not all(v == 0 for v in sp.flatten(array))]

def coefficient_denominator(Psi):
    return sp.lcm(list(map(lambda coeff : sp.fraction(coeff)[1],
                    sp.flatten(list(map(lambda p : p.as_poly().coeffs() if p!=0 else 0,
                                        sp.flatten(Psi)))))))

def coefficient_numerator(Psi):
    return sp.gcd(list(map(lambda coeff : sp.fraction(coeff)[0],
                    sp.flatten(list(map(lambda p : p.as_poly().coeffs() if p!=0 else 0,
                                        sp.flatten(Psi)))))))

def standard_inner_product(v,w):
    return (v.transpose()*w)[0]

def collect_weight_basis_slow(highest_weight_vector,highest_weight,action):
    weights = {}
    for j in range(0,max(highest_weight)+1):
        for k in range(0,j+1):
            weights.update({(j,k):get_weight_vectors(highest_weight_vector,highest_weight,(j,k),action)})
    return weights

def get_forms_of_degree_and_weight(degree,highest_weigth,weight):
    return [p*f for polys in P[degree] 
            for forms in V[highest_weigth]
            for p in P[degree][polys]
            for f in V[highest_weigth][forms]
            if sp.Matrix(polys)+sp.Matrix(forms) == sp.Matrix(weight)]

def expand_in_orthogonal_basis(vector,basis):
    return [form_inner_product(basis[j],vector)/form_inner_product(basis[j],basis[j]) for j in range(len(basis))]

def expand_in_ONB(vector,basis):
    return [form_inner_product(basis[j],vector)/sp.sqrt(form_inner_product(basis[j],basis[j])) for j in range(len(basis))]

def get_coeffs_of_invariant_operator(operator,basis):
    forms = [operator(form) for form in basis]
    return sp.Matrix([[form_inner_product(forms[i],basis[j])/(sp.sqrt(form_inner_product(basis[i],basis[i]))*sp.sqrt(form_inner_product(basis[j],basis[j]))) for i in range(len(basis))] for j in range(len(basis))])

